  }
  :root input::placeholder,
  :root textarea::placeholder {
    color: #a6adc8 !important;
  }
  :root div.book .programlisting,
  :root div.appendix .programlisting {
    background-color: #313244 !important;
  }
  :root hr,
  :root div.toc {
    border-top-color: transparent;
